"use client";

export { default as LightSphere } from "./LightSphere";
export type {
  LightSphereConfig,
  LightSphereProps,
  LightSphereViewMode,
  Vector3Like,
} from "./LightSphere.types";
export { BEAM_CONFIG, SPHERE_RADIUS } from "./LightSphere.constants";
export { sphericalPoint } from "./utils/geometry";

export { default as LightSpherePanel } from "./LightSpherePanel";
export { DEFAULT_LIGHT_SPHERE_PANEL_VALUE, LIGHT_POSITION_PRESETS } from "./LightSphere.constants";
export type { LightPositionKey, LightSpherePanelValue, LightSpherePanelProps, LightSphereActionButtonProps } from "./LightSphere.types";

import registryDefaultImage from "./registry-default-image";
import React, { Suspense, useEffect, useRef } from "react";
import { Canvas } from "@react-three/fiber";
import { BEAM_CONFIG, SPHERE_RADIUS } from "./LightSphere.constants";
import LightSphereScene from "./parts/LightSphereScene";
import type { LightSphereConfig, LightSphereProps } from "./LightSphere.types";

export default function LightSphere({
  imageUrl = registryDefaultImage,
  color = BEAM_CONFIG.color,
  spread = BEAM_CONFIG.spread,
  intensity = BEAM_CONFIG.intensity,
  glowRadius = BEAM_CONFIG.glowRadius,
  glowIntensity = BEAM_CONFIG.glowIntensity,
  baseLineOpacity = BEAM_CONFIG.baseLineOpacity,
  sphereRadius = SPHERE_RADIUS,
  viewMode = "front",
  targetPosition,
  onLightMove,
  onLightSettle,
  className = "",
  style,
}: LightSphereProps) {
  const configRef = useRef<LightSphereConfig>({
    color,
    spread,
    intensity,
    glowRadius,
    glowIntensity,
    baseLineOpacity,
    sphereRadius,
  });

  const targetPosRef = useRef(targetPosition);

  // 将属性同步到 ref，避免触发 Canvas 重新渲染。
  useEffect(() => {
    configRef.current = {
      color,
      spread,
      intensity,
      glowRadius,
      glowIntensity,
      baseLineOpacity,
      sphereRadius,
    };
  }, [color, spread, intensity, glowRadius, glowIntensity, baseLineOpacity, sphereRadius]);

  // 将目标位置同步到 ref。
  useEffect(() => {
    targetPosRef.current = targetPosition;
  }, [targetPosition]);

  return (
    <div
      className={className}
      style={{ width: "100%", height: "100%", ...style }}
    >
      <Canvas
        camera={{ position: [0, 0.12, 8.65], fov: 34 }}
        gl={{
          antialias: true,
          alpha: false,
          powerPreference: "high-performance",
        }}
        dpr={[1, 1.5]}
      >
        <Suspense fallback={null}>
          <LightSphereScene
            configRef={configRef}
            targetPosRef={targetPosRef}
            imageUrl={imageUrl}
            viewMode={viewMode}
            onLightMove={onLightMove}
            onLightSettle={onLightSettle}
          />
        </Suspense>
      </Canvas>
    </div>
  );
}

import * as THREE from "three";
import type { LightSphereConfig, LightPositionKey, LightSpherePanelValue } from "./LightSphere.types";

export const SPHERE_RADIUS = 2.45;
export const TARGET = new THREE.Vector3(0, 0.05, 0);

export const BEAM_CONFIG: Omit<LightSphereConfig, "sphereRadius"> = {
  color: "#ff2200",
  spread: 0.38,
  intensity: 0.72,
  glowRadius: 1.8,
  glowIntensity: 1.2,
  baseLineOpacity: 0.045,
};

export const LIGHT_POSITION_PRESETS: { key: LightPositionKey; label: string; lat: number; lon: number }[] = [
  { key: "left", label: "左侧", lat: 0, lon: 170 },
  { key: "top", label: "顶部", lat: 90, lon: 0 },
  { key: "right", label: "右侧", lat: 0, lon: 10 },
  { key: "front", label: "前方", lat: 0, lon: 90 },
  { key: "bottom", label: "底部", lat: -90, lon: 0 },
  { key: "back", label: "后方", lat: 0, lon: -90 },
];

export const DEFAULT_LIGHT_SPHERE_PANEL_VALUE: LightSpherePanelValue = {
  position: { x: 0, y: 0, z: SPHERE_RADIUS },
  intensity: 0.5,
  colorTemperature: 5600,
  activePosition: "front",
  viewMode: "perspective",
  rimLightEnabled: true,
};

import type { ComponentType, CSSProperties, MouseEventHandler, MutableRefObject } from "react";
import type { ThreeEvent } from "@react-three/fiber";
import type * as THREE from "three";

export type Vector3Like = {
  x: number;
  y: number;
  z: number;
};

export type LightSphereConfig = {
  color: string;
  spread: number;
  intensity: number;
  glowRadius: number;
  glowIntensity: number;
  baseLineOpacity: number;
  sphereRadius: number;
};

export type LightSphereViewMode = "front" | "perspective";

export type LightSphereProps = Partial<LightSphereConfig> & {
  imageUrl?: string;
  viewMode?: LightSphereViewMode;
  targetPosition?: Vector3Like | null;
  onLightMove?: (position: Vector3Like) => void;
  onLightSettle?: (position: Vector3Like) => void;
  className?: string;
  style?: CSSProperties;
};

export type LightSphereConfigRef = MutableRefObject<LightSphereConfig>;
export type LightPositionRef = MutableRefObject<THREE.Vector3>;

export type LightDragHandlers = {
  onPointerDown: (event: ThreeEvent<PointerEvent>) => void;
  onPointerMove: (event: ThreeEvent<PointerEvent>) => void;
  onPointerUp: (event: ThreeEvent<PointerEvent>) => void;
  onPointerCancel: () => void;
};

export type LightPositionKey = "left" | "top" | "right" | "front" | "bottom" | "back";

export type LightSpherePanelValue = {
  position: Vector3Like;
  intensity: number;
  colorTemperature: number;
  activePosition: LightPositionKey | null;
  viewMode: LightSphereViewMode;
  /** Output option, matching tamen-web; does not add a second preview light. */
  rimLightEnabled: boolean;
};

export type LightSphereActionButtonProps = {
  className: string;
  value: LightSpherePanelValue;
  input?: unknown;
  onClick: MouseEventHandler<HTMLButtonElement>;
  disabled: boolean;
  loading: boolean;
};

export type LightSpherePanelProps = {
  imageUrl?: string;
  value?: Partial<LightSpherePanelValue>;
  defaultValue?: Partial<LightSpherePanelValue>;
  onChange?: (value: LightSpherePanelValue) => void;
  onChangeEnd?: (value: LightSpherePanelValue) => void;
  onClose?: () => void;
  actionButton?: ComponentType<LightSphereActionButtonProps>;
  actionInput?: unknown;
  actionLoading?: boolean;
  actionDisabled?: boolean;
  onAction?: (payload: { value: LightSpherePanelValue; input?: unknown }, event: Parameters<MouseEventHandler<HTMLButtonElement>>[0]) => void;
  className?: string;
  style?: CSSProperties;
};

import { useEffect, useRef } from "react";
import type { ThreeEvent } from "@react-three/fiber";
import * as THREE from "three";
import type { LightDragHandlers, LightPositionRef } from "../LightSphere.types";

type PointerCaptureTarget = EventTarget & {
  setPointerCapture?: (pointerId: number) => void;
  releasePointerCapture?: (pointerId: number) => void;
};

export function useLightDrag(
  lightRef: LightPositionRef,
  settleLight: () => void,
  sphereRadius: number,
): LightDragHandlers {
  const dragging = useRef(false);
  const settleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearSettleTimer = () => {
    if (settleTimer.current) {
      clearTimeout(settleTimer.current);
      settleTimer.current = null;
    }
  };

  useEffect(() => () => clearSettleTimer(), []);

  const updateFromPointer = (event: ThreeEvent<PointerEvent>) => {
    event.stopPropagation();
    clearSettleTimer();

    const hit = new THREE.Vector3();
    const sphere = new THREE.Sphere(new THREE.Vector3(0, 0, 0), sphereRadius);
    const hasHit = event.ray?.intersectSphere(sphere, hit);

    if (hasHit) {
      lightRef.current.copy(hit);
    } else if (event.point) {
      const projected = event.point.clone().normalize().multiplyScalar(sphereRadius);
      if (lightRef.current.distanceTo(projected) < 1.5) {
        lightRef.current.copy(projected);
      }
    }

    settleTimer.current = setTimeout(settleLight, 520);
  };

  return {
    onPointerDown: (event) => {
      clearSettleTimer();
      const target = event.target as PointerCaptureTarget;
      target.setPointerCapture?.(event.pointerId);
      dragging.current = true;
      updateFromPointer(event);
    },
    onPointerMove: (event) => {
      if (dragging.current) updateFromPointer(event);
    },
    onPointerUp: (event) => {
      clearSettleTimer();
      const target = event.target as PointerCaptureTarget;
      target.releasePointerCapture?.(event.pointerId);
      dragging.current = false;
      settleLight();
    },
    onPointerCancel: () => {
      dragging.current = false;
      settleLight();
    },
  };
}

import React, { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { TARGET } from "../LightSphere.constants";
import type { LightPositionRef, LightSphereConfigRef } from "../LightSphere.types";
import { beamVertex, beamFragment } from "../shaders";

type BeamProps = {
  lightRef: LightPositionRef;
  configRef: LightSphereConfigRef;
};

export default function Beam({ lightRef, configRef }: BeamProps) {
  const mesh = useRef<THREE.Mesh>(null);
  const cone = useMemo(() => new THREE.ConeGeometry(1, 1, 96, 1, true), []);
  const material = useMemo(
    () =>
      new THREE.ShaderMaterial({
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
        uniforms: {
          color: { value: new THREE.Color(configRef.current.color) },
          uIntensity: { value: configRef.current.intensity },
        },
        vertexShader: beamVertex,
        fragmentShader: beamFragment,
      }),
    [],
  );

  useFrame(() => {
    const cfg = configRef.current;
    material.uniforms.color.value.set(cfg.color);
    material.uniforms.uIntensity.value = cfg.intensity;

    const lightPosition = lightRef.current;
    const direction = TARGET.clone().sub(lightPosition);
    const length = direction.length();
    if (length < 0.001) return;
    const forward = direction.normalize();
    const midpoint = lightPosition.clone().add(TARGET).multiplyScalar(0.5);
    const radius = Math.min(0.72, length * cfg.spread);

    if (!mesh.current) return;
    mesh.current.position.copy(midpoint);
    mesh.current.scale.set(radius, length, radius);
    mesh.current.quaternion.setFromUnitVectors(
      new THREE.Vector3(0, -1, 0),
      forward,
    );
  });

  return <mesh ref={mesh} geometry={cone} material={material} renderOrder={25} />;
}

import React, { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import type {
  LightDragHandlers,
  LightPositionRef,
  LightSphereConfigRef,
} from "../LightSphere.types";
import { makeLatitude, makeMeridian, makeRing, generateSnapPoints } from "../utils/geometry";
import { glowLineVertex, glowLineFragment, glassSphereVertex, glassSphereFragment } from "../shaders";

type GlowLineProps = {
  points: number[][];
  lightRef: LightPositionRef;
  configRef: LightSphereConfigRef;
  baseOpacity: number;
};

function GlowLine({ points, lightRef, configRef, baseOpacity }: GlowLineProps) {
  const lineObj = useMemo(() => {
    const geo = new THREE.BufferGeometry();
    const positions = new Float32Array(points.length * 3);
    for (let i = 0; i < points.length; i++) {
      positions[i * 3] = points[i][0];
      positions[i * 3 + 1] = points[i][1];
      positions[i * 3 + 2] = points[i][2];
    }
    geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));

    const mat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: {
        uLightPos: { value: new THREE.Vector3() },
        uLightColor: { value: new THREE.Color(configRef.current.color) },
        uGlowRadius: { value: configRef.current.glowRadius },
        uGlowIntensity: { value: configRef.current.glowIntensity },
        uBaseOpacity: { value: baseOpacity },
      },
      vertexShader: glowLineVertex,
      fragmentShader: glowLineFragment,
    });

    return new THREE.Line(geo, mat);
  }, [points, baseOpacity]);

  useFrame(() => {
    if (lineObj.material) {
      const cfg = configRef.current;
      lineObj.material.uniforms.uLightPos.value.copy(lightRef.current);
      lineObj.material.uniforms.uLightColor.value.set(cfg.color);
      lineObj.material.uniforms.uGlowRadius.value = cfg.glowRadius;
      lineObj.material.uniforms.uGlowIntensity.value = cfg.glowIntensity;
    }
  });

  return <primitive object={lineObj} />;
}

type SnapPointProps = {
  point: THREE.Vector3;
  lightRef: LightPositionRef;
  configRef: LightSphereConfigRef;
  important: boolean;
};

function SnapPoint({ point, lightRef, configRef, important }: SnapPointProps) {
  const mesh = useRef<THREE.Mesh>(null);
  const material = useRef<THREE.MeshBasicMaterial>(null);

  useFrame(() => {
    const cfg = configRef.current;
    const distance = point.distanceTo(lightRef.current);
    const active = 1 - THREE.MathUtils.smoothstep(distance, 0.12, cfg.glowRadius * 0.5);
    const baseOpacity = important ? 0.32 : 0.18;
    const opacity = baseOpacity + active * 0.62;
    const scale = (important ? 1.2 : 1) + active * 1.1;

    if (!mesh.current || !material.current) return;
    material.current.opacity = opacity;
    const beamColor = new THREE.Color(cfg.color);
    material.current.color.copy(beamColor).multiplyScalar(0.3 + active * 0.7);
    const baseColor = new THREE.Color("#e7e7e2");
    material.current.color.lerp(baseColor, 1.0 - active);
    mesh.current.scale.setScalar(scale);
  });

  return (
    <mesh ref={mesh} position={point}>
      <sphereGeometry args={[important ? 0.05 : 0.034, 16, 16]} />
      <meshBasicMaterial
        ref={material}
        color="#e7e7e2"
        transparent
        opacity={important ? 0.32 : 0.18}
        depthWrite={false}
      />
    </mesh>
  );
}

type GlassSphereProps = {
  lightRef: LightPositionRef;
  configRef: LightSphereConfigRef;
  dragHandlers: LightDragHandlers;
};

export default function GlassSphere({ lightRef, configRef, dragHandlers }: GlassSphereProps) {
  const sphereRadius = configRef.current.sphereRadius;

  const rings = useMemo(
    () => [
      makeLatitude(-54, sphereRadius),
      makeLatitude(-27, sphereRadius),
      makeLatitude(0, sphereRadius),
      makeLatitude(27, sphereRadius),
      makeLatitude(54, sphereRadius),
      makeMeridian(34, sphereRadius),
      makeMeridian(62, sphereRadius),
      makeMeridian(90, sphereRadius),
      makeMeridian(118, sphereRadius),
      makeMeridian(146, sphereRadius),
      makeRing("z", 0, sphereRadius),
    ],
    [sphereRadius],
  );

  const snapPoints = useMemo(() => generateSnapPoints(sphereRadius), [sphereRadius]);

  return (
    <group>
      <mesh {...dragHandlers}>
        <sphereGeometry args={[sphereRadius, 96, 96]} />
        <shaderMaterial
          transparent
          side={THREE.DoubleSide}
          depthWrite={false}
          uniforms={{
            uColor: { value: new THREE.Color("#c7c7c3") },
          }}
          vertexShader={glassSphereVertex}
          fragmentShader={glassSphereFragment}
        />
      </mesh>

      {rings.map((points, index) => (
        <GlowLine
          key={index}
          points={points}
          lightRef={lightRef}
          configRef={configRef}
          baseOpacity={index === 10 ? 0.09 : configRef.current.baseLineOpacity}
        />
      ))}

      {snapPoints.map((point, index) => (
        <SnapPoint
          key={index}
          point={point}
          lightRef={lightRef}
          configRef={configRef}
          important={index > 24}
        />
      ))}
    </group>
  );
}

import React, { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { TARGET } from "../LightSphere.constants";
import type {
  LightDragHandlers,
  LightPositionRef,
  LightSphereConfigRef,
} from "../LightSphere.types";
import { lightHandleVertex, lightHandleFragment, glowDiscVertex, glowDiscFragment } from "../shaders";

type LightHandleProps = {
  lightRef: LightPositionRef;
  configRef: LightSphereConfigRef;
  dragHandlers: LightDragHandlers;
};

export default function LightHandle({ lightRef, configRef, dragHandlers }: LightHandleProps) {
  const group = useRef<THREE.Group>(null);
  const sphereMaterial = useRef<THREE.ShaderMaterial>(null);
  const glowMesh = useRef<THREE.Mesh>(null);
  const glowMaterial = useRef<THREE.ShaderMaterial>(null);

  useFrame(() => {
    const cfg = configRef.current;
    if (!group.current) return;
    group.current.position.copy(lightRef.current);

    const beamDir = TARGET.clone().sub(lightRef.current).normalize();

    if (sphereMaterial.current) {
      sphereMaterial.current.uniforms.uBeamColor.value.set(cfg.color);
      sphereMaterial.current.uniforms.uBeamDir.value.copy(beamDir);
    }
    if (glowMaterial.current) {
      glowMaterial.current.uniforms.uBeamColor.value.set(cfg.color);
    }

    if (glowMesh.current) {
      const discPos = beamDir.clone().multiplyScalar(0.16);
      glowMesh.current.position.copy(discPos);
      glowMesh.current.lookAt(discPos.clone().add(beamDir));
    }
  });

  const sphereShader = useMemo(() => ({
    uniforms: {
      uBeamColor: { value: new THREE.Color(configRef.current.color) },
      uBeamDir: { value: new THREE.Vector3(0, -1, 0) },
    },
    vertexShader: lightHandleVertex,
    fragmentShader: lightHandleFragment,
  }), []);

  const glowDiscShader = useMemo(() => ({
    uniforms: {
      uBeamColor: { value: new THREE.Color(configRef.current.color) },
    },
    vertexShader: glowDiscVertex,
    fragmentShader: glowDiscFragment,
  }), []);

  return (
    <group ref={group} position={lightRef.current}>
      <mesh {...dragHandlers} renderOrder={20}>
        <sphereGeometry args={[0.18, 32, 32]} />
        <shaderMaterial
          ref={sphereMaterial}
          {...sphereShader}
          depthWrite={true}
          depthTest={true}
          transparent={true}
        />
      </mesh>
      <mesh ref={glowMesh} renderOrder={30} raycast={() => null}>
        <planeGeometry args={[0.5, 0.5]} />
        <shaderMaterial
          ref={glowMaterial}
          {...glowDiscShader}
          transparent
          depthWrite={false}
          blending={THREE.AdditiveBlending}
          side={THREE.DoubleSide}
        />
      </mesh>
    </group>
  );
}

import React, { useRef, useMemo } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";
import * as THREE from "three";
import { TARGET } from "../LightSphere.constants";
import type {
  LightSphereConfigRef,
  LightSphereViewMode,
  Vector3Like,
} from "../LightSphere.types";
import {
  sphericalPoint,
  generateSnapPoints,
  closestSnap,
} from "../utils/geometry";
import { useLightDrag } from "../hooks/useLightDrag";
import GlassSphere from "./GlassSphere";
import Beam from "./Beam";
import LightHandle from "./LightHandle";
import PhotoPlane from "./PhotoPlane";

type SnapAnimation = {
  from: THREE.Vector3;
  to: THREE.Vector3;
  elapsed: number;
  duration: number;
};

type LightSphereSceneProps = {
  configRef: LightSphereConfigRef;
  targetPosRef: React.MutableRefObject<Vector3Like | null | undefined>;
  imageUrl: string;
  viewMode: LightSphereViewMode;
  onLightMove?: (position: Vector3Like) => void;
  onLightSettle?: (position: Vector3Like) => void;
};

export default function LightSphereScene({
  configRef,
  targetPosRef,
  imageUrl,
  viewMode,
  onLightMove,
  onLightSettle,
}: LightSphereSceneProps) {
  const sphereRadius = configRef.current.sphereRadius;
  const lightRef = useRef(sphericalPoint(-45, 146, sphereRadius));
  const snapAnimation = useRef<SnapAnimation | null>(null);
  const lastTargetPos = useRef<Vector3Like | null | undefined>(null);
  const spotTarget = useRef<THREE.Object3D>(null);
  const spotLight = useRef<THREE.SpotLight>(null);
  const { camera } = useThree();

  const snapPoints = useMemo(
    () => generateSnapPoints(sphereRadius),
    [sphereRadius],
  );

  const settleLight = () => {
    const target = closestSnap(lightRef.current, snapPoints);
    if (lightRef.current.distanceTo(target) < 0.002) {
      if (onLightSettle) {
        const p = lightRef.current;
        onLightSettle({ x: p.x, y: p.y, z: p.z });
      }
      return;
    }

    snapAnimation.current = {
      from: lightRef.current.clone(),
      to: target,
      elapsed: 0,
      duration: 0.42,
    };
  };

  const dragHandlers = useLightDrag(lightRef, settleLight, sphereRadius);

  useFrame((_, delta) => {
    const desiredCameraPosition =
      viewMode === "perspective"
        ? new THREE.Vector3(6.1, 1.2, 6.1)
        : new THREE.Vector3(0, 0.12, 8.65);

    camera.position.lerp(desiredCameraPosition, 0.12);
    camera.lookAt(0, viewMode === "perspective" ? 0.2 : 0.05, 0);
    if (spotLight.current) spotLight.current.position.copy(lightRef.current);

    // 检查父组件传入的目标位置是否变化（来自位置预设按钮）。
    const tp = targetPosRef?.current;
    if (tp && tp !== lastTargetPos.current) {
      lastTargetPos.current = tp;
      const to = new THREE.Vector3(tp.x, tp.y, tp.z);
      snapAnimation.current = {
        from: lightRef.current.clone(),
        to,
        elapsed: 0,
        duration: 0.5,
      };
    }

    // 触发灯光移动回调。
    if (onLightMove) {
      const p = lightRef.current;
      onLightMove({ x: p.x, y: p.y, z: p.z });
    }

    if (!snapAnimation.current) return;

    const animation = snapAnimation.current;
    animation.elapsed += delta;
    const t = Math.min(animation.elapsed / animation.duration, 1);
    const eased = 1 - Math.pow(1 - t, 3);
    const point = animation.from.clone().lerp(animation.to, eased);
    lightRef.current.copy(point);

    if (t >= 1) {
      lightRef.current.copy(animation.to);
      snapAnimation.current = null;
      if (onLightSettle) {
        const p = animation.to;
        onLightSettle({ x: p.x, y: p.y, z: p.z });
      }
    }
  });

  const cfg = configRef.current;

  return (
    <>
      <color attach="background" args={["#20201f"]} />
      <fog attach="fog" args={["#20201f", 4.7, 8.5]} />

      <ambientLight intensity={0.42} />
      <directionalLight position={[1.8, 2.5, 2.2]} intensity={0.42} />
      <spotLight
        ref={spotLight}
        position={lightRef.current}
        target={spotTarget.current ?? undefined}
        color={cfg.color}
        intensity={24}
        angle={cfg.spread}
        penumbra={0.75}
        distance={6}
      />
      <object3D ref={spotTarget} position={TARGET} />

      <GlassSphere
        lightRef={lightRef}
        configRef={configRef}
        dragHandlers={dragHandlers}
      />
      <Beam lightRef={lightRef} configRef={configRef} />
      <LightHandle
        lightRef={lightRef}
        configRef={configRef}
        dragHandlers={dragHandlers}
      />
      <PhotoPlane lightRef={lightRef} imageUrl={imageUrl} viewMode={viewMode} />

      <OrbitControls
        enabled={false}
        enablePan={false}
        enableZoom={false}
        rotateSpeed={0.28}
        minPolarAngle={Math.PI * 0.33}
        maxPolarAngle={Math.PI * 0.68}
      />
    </>
  );
}

import { useFrame, useLoader } from "@react-three/fiber";
import { useMemo, useRef } from "react";
import * as THREE from "three";

import type { LightPositionRef, LightSphereViewMode } from "../LightSphere.types";
import { getPhotoPlaneSize } from "../utils/photo-plane-size";
import { photoPlaneFragment, photoPlaneVertex } from "../shaders";

type PhotoPlaneProps = {
  lightRef: LightPositionRef;
  imageUrl: string;
  viewMode?: LightSphereViewMode;
};

export default function PhotoPlane({
  lightRef,
  imageUrl,
  viewMode = "front",
}: PhotoPlaneProps) {
  const texture = useLoader(THREE.TextureLoader, imageUrl);
  const material = useRef<THREE.ShaderMaterial>(null);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 8;
  const image = texture.image as HTMLImageElement;
  const planeSize = getPhotoPlaneSize(
    image.naturalWidth || image.width,
    image.naturalHeight || image.height,
  );
  const uniforms = useMemo(
    () => ({
      uMap: { value: texture },
      uLight: { value: lightRef.current.clone() },
    }),
    [lightRef, texture],
  );

  useFrame(() => {
    if (material.current)
      material.current.uniforms.uLight.value.copy(lightRef.current);
  });

  return (
    <group
      position={[0, 0.02, -0.02]}
      rotation={viewMode === "perspective" ? [0, -0.08, 0] : [0, -0.08, 0]}
    >
      <mesh castShadow receiveShadow>
        <planeGeometry args={[planeSize.width, planeSize.height, 96, 96]} />
        <shaderMaterial
          ref={material}
          side={THREE.DoubleSide}
          uniforms={uniforms}
          vertexShader={photoPlaneVertex}
          fragmentShader={photoPlaneFragment}
        />
      </mesh>
      <mesh position={[0, 0, -0.018]}>
        <boxGeometry
          args={[planeSize.width + 0.04, planeSize.height + 0.04, 0.035]}
        />
        <meshStandardMaterial
          color="#111111"
          roughness={0.7}
          metalness={0.05}
        />
      </mesh>
    </group>
  );
}

"use client";

// 发光网格线着色器
export const glowLineVertex = `
  uniform vec3 uLightPos;
  uniform float uGlowRadius;
  uniform float uGlowIntensity;
  uniform float uBaseOpacity;

  varying float vGlow;

  void main() {
    vec4 worldPos = modelMatrix * vec4(position, 1.0);
    float dist = distance(worldPos.xyz, uLightPos);
    float proximity = 1.0 - smoothstep(0.0, uGlowRadius, dist);
    vGlow = uBaseOpacity + pow(proximity, 2.0) * uGlowIntensity;
    gl_Position = projectionMatrix * viewMatrix * worldPos;
  }
`;

export const glowLineFragment = `
  uniform vec3 uLightColor;
  varying float vGlow;

  void main() {
    vec3 color = mix(vec3(1.0), uLightColor, smoothstep(0.08, 0.6, vGlow));
    gl_FragColor = vec4(color, vGlow);
  }
`;

// 玻璃球体着色器
export const glassSphereVertex = `
  varying vec3 vNormal;
  varying vec3 vWorld;
  void main() {
    vNormal = normalize(normalMatrix * normal);
    vec4 world = modelMatrix * vec4(position, 1.0);
    vWorld = world.xyz;
    gl_Position = projectionMatrix * viewMatrix * world;
  }
`;

export const glassSphereFragment = `
  uniform vec3 uColor;
  varying vec3 vNormal;
  varying vec3 vWorld;
  void main() {
    vec3 viewDir = normalize(cameraPosition - vWorld);
    vec3 n = gl_FrontFacing ? normalize(vNormal) : -normalize(vNormal);
    float NdotV = max(dot(n, viewDir), 0.0);
    float fresnel = pow(1.0 - NdotV, 2.5);
    float alpha = 0.008 + fresnel * 0.24;
    // 背面降低透明度，避免侧视角出现叠加过亮。
    if (!gl_FrontFacing) alpha *= 0.3;
    gl_FragColor = vec4(uColor, alpha);
  }
`;

// 灯光手柄球体着色器
export const lightHandleVertex = `
  uniform vec3 uBeamDir;
  varying vec3 vNormal;
  varying vec3 vViewDir;
  varying float vBeamFace;
  void main() {
    vNormal = normalize(normalMatrix * normal);
    vec4 worldPos = modelMatrix * vec4(position, 1.0);
    vViewDir = normalize(cameraPosition - worldPos.xyz);

    vec3 worldNormal = normalize((modelMatrix * vec4(normal, 0.0)).xyz);
    vBeamFace = max(dot(worldNormal, uBeamDir), 0.0);

    gl_Position = projectionMatrix * viewMatrix * worldPos;
  }
`;

export const lightHandleFragment = `
  uniform vec3 uBeamColor;
  uniform vec3 uBeamDir;
  varying vec3 vNormal;
  varying vec3 vViewDir;
  varying float vBeamFace;
  void main() {
    vec3 baseColor = vec3(0.02, 0.02, 0.02);
    float fresnel = pow(1.0 - abs(dot(vNormal, vViewDir)), 3.5);
    vec3 rimLight = vec3(0.4) * fresnel * 0.15;
    float beamGlow = pow(vBeamFace, 5.0) * 3.0;
    vec3 beamContrib = uBeamColor * beamGlow;
    vec3 finalColor = baseColor + rimLight + beamContrib;
    gl_FragColor = vec4(finalColor, 1.0);
  }
`;

// 灯光手柄光晕圆片着色器
export const glowDiscVertex = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

export const glowDiscFragment = `
  uniform vec3 uBeamColor;
  varying vec2 vUv;
  void main() {
    float dist = distance(vUv, vec2(0.5));
    float glow = 1.0 - smoothstep(0.0, 0.5, dist);
    glow = pow(glow, 1.8);
    vec3 color = uBeamColor * 1.5;
    gl_FragColor = vec4(color, glow * 0.7);
  }
`;

// 光束锥体着色器
export const beamVertex = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

export const beamFragment = `
  uniform vec3 color;
  uniform float uIntensity;
  varying vec2 vUv;
  void main() {
    float openAtSource = smoothstep(0.02, 0.16, vUv.y);
    float fadeToImage = 1.0 - smoothstep(0.25, 0.98, vUv.y);
    float sourceHotspot = 1.0 - smoothstep(0.0, 0.22, vUv.y);
    float beam = openAtSource * (0.035 + fadeToImage * 0.54 + sourceHotspot * 0.46);
    gl_FragColor = vec4(color, beam * uIntensity);
  }
`;

// 照片平面着色器
export const photoPlaneVertex = `
  varying vec2 vUv;
  varying vec3 vWorld;
  void main() {
    vUv = uv;
    vec4 world = modelMatrix * vec4(position, 1.0);
    vWorld = world.xyz;
    gl_Position = projectionMatrix * viewMatrix * world;
  }
`;

export const photoPlaneFragment = `
  uniform sampler2D uMap;
  uniform vec3 uLight;
  varying vec2 vUv;
  varying vec3 vWorld;

  void main() {
    vec3 tex = texture2D(uMap, vUv).rgb;
    vec3 toLight = normalize(uLight - vWorld);
    float lambert = clamp(dot(toLight, vec3(0.0, 0.0, 1.0)), 0.0, 1.0);
    vec2 lightUv = vec2(0.5 - uLight.x * 0.16, 0.52 + uLight.y * 0.18);
    float spot = 1.0 - smoothstep(0.0, 0.78, distance(vUv, lightUv));
    float sweep = smoothstep(-2.35, 2.35, uLight.x) * (1.0 - vUv.x) + (1.0 - smoothstep(-2.35, 2.35, uLight.x)) * vUv.x;
    vec3 lit = tex * (0.58 + lambert * 0.52 + spot * 0.82 + sweep * 0.18);
    vec3 coolShadow = vec3(0.035, 0.045, 0.05) * (1.0 - spot) * 0.45;
    gl_FragColor = vec4(lit + coolShadow, 1.0);
  }
`;

import * as THREE from "three";

export type RingAxis = "x" | "y" | "z";
export type Point3Tuple = [number, number, number];

export function sphericalPoint(
  latDeg: number,
  lonDeg: number,
  radius: number,
): THREE.Vector3 {
  const lat = THREE.MathUtils.degToRad(latDeg);
  const lon = THREE.MathUtils.degToRad(lonDeg);
  return new THREE.Vector3(
    radius * Math.cos(lat) * Math.cos(lon),
    radius * Math.sin(lat),
    radius * Math.cos(lat) * Math.sin(lon),
  );
}

export function makeRing(
  axis: RingAxis,
  angleDeg: number,
  radius: number,
): Point3Tuple[] {
  const points: Point3Tuple[] = [];
  const r = radius * Math.cos(THREE.MathUtils.degToRad(angleDeg));
  const offset = radius * Math.sin(THREE.MathUtils.degToRad(angleDeg));

  for (let i = 0; i <= 160; i += 1) {
    const a = (i / 160) * Math.PI * 2;
    if (axis === "y") points.push([Math.cos(a) * r, offset, Math.sin(a) * r]);
    if (axis === "x") points.push([offset, Math.cos(a) * r, Math.sin(a) * r]);
    if (axis === "z") points.push([Math.cos(a) * r, Math.sin(a) * r, offset]);
  }
  return points;
}

export function makeLatitude(latDeg: number, radius: number): Point3Tuple[] {
  const points: Point3Tuple[] = [];
  for (let i = 0; i <= 140; i += 1) {
    const lon = (i / 140) * 180;
    const point = sphericalPoint(latDeg, lon, radius + 0.012);
    points.push([point.x, point.y, point.z]);
  }
  return points;
}

export function makeMeridian(lonDeg: number, radius: number): Point3Tuple[] {
  const points: Point3Tuple[] = [];
  for (let i = 0; i <= 140; i += 1) {
    const lat = -78 + (i / 140) * 156;
    const point = sphericalPoint(lat, lonDeg, radius + 0.014);
    points.push([point.x, point.y, point.z]);
  }
  return points;
}

export function generateSnapPoints(radius: number): THREE.Vector3[] {
  return [
    ...[-54, -27, 0, 27, 54].flatMap((lat) =>
      [34, 62, 90, 118, 146].map((lon) => sphericalPoint(lat, lon, radius)),
    ),
    sphericalPoint(90, 0, radius),
    sphericalPoint(-90, 0, radius),
    sphericalPoint(0, 10, radius),
    sphericalPoint(0, 170, radius),
  ];
}

export function closestSnap(
  point: THREE.Vector3,
  snapPoints: THREE.Vector3[],
): THREE.Vector3 {
  let nearest = point;
  let bestDistance = Infinity;

  for (const snapPoint of snapPoints) {
    const distance = point.distanceTo(snapPoint);
    if (distance < bestDistance) {
      bestDistance = distance;
      nearest = snapPoint;
    }
  }

  if (bestDistance > 1.2) return point.clone();
  return nearest.clone();
}

import registryDefaultImage from "./registry-default-image";
import React, { useMemo, useRef, useState } from "react";
import { ArrowUp, LoaderCircle, RotateCcw } from "lucide-react";
import { BEAM_CONFIG, DEFAULT_LIGHT_SPHERE_PANEL_VALUE, LIGHT_POSITION_PRESETS, SPHERE_RADIUS } from "./LightSphere.constants";
import type { LightSphereActionButtonProps, LightSpherePanelProps, LightSpherePanelValue } from "./LightSphere.types";
import { colorTemperatureToHex } from "./utils/color-temperature";
import { sphericalPoint } from "./utils/geometry";
import { resolveLightPositionPresetKey } from "./utils/position-preset";
import { LightingControls } from "./parts/LightingControls";
import LightSphere from "./LightSphere";

function normalizeValue(value?: Partial<LightSpherePanelValue>): LightSpherePanelValue {
  const preset = LIGHT_POSITION_PRESETS.find(({ key }) => key === value?.activePosition);
  const point = value?.position ?? (preset ? sphericalPoint(preset.lat, preset.lon, SPHERE_RADIUS) : DEFAULT_LIGHT_SPHERE_PANEL_VALUE.position);
  return {
    ...DEFAULT_LIGHT_SPHERE_PANEL_VALUE,
    ...value,
    position: value?.position ?? { x: point.x, y: point.y, z: point.z },
    activePosition: resolveLightPositionPresetKey(point),
    intensity: Math.min(1, Math.max(0, value?.intensity ?? 0.5)),
    colorTemperature: Math.min(10000, Math.max(2400, value?.colorTemperature ?? 5600)),
  };
}

function DefaultActionButton({ className, onClick, disabled, loading }: LightSphereActionButtonProps) {
  return (
    <button type="button" className={className} onClick={onClick} disabled={disabled} aria-busy={loading} aria-label={loading ? "处理中" : "应用打光"} title={loading ? "处理中" : "应用打光"}>
      {loading ? <LoaderCircle size={14} className="animate-spin" aria-hidden="true" /> : <ArrowUp size={16} aria-hidden="true" />}
    </button>
  );
}

export default function LightSpherePanel({
  imageUrl = registryDefaultImage, value, defaultValue, onChange, onChangeEnd, onClose,
  actionButton: ActionButton = DefaultActionButton, actionInput, actionLoading = false, actionDisabled = false,
  onAction, className = "", style,
}: LightSpherePanelProps) {
  const [internalValue, setInternalValue] = useState(() => normalizeValue(defaultValue));
  const currentValue = useMemo(() => value === undefined ? internalValue : normalizeValue(value), [value, internalValue]);
  const latestValue = useRef(currentValue);
  latestValue.current = currentValue;
  const pending = useRef(false);

  const update = (patch: Partial<LightSpherePanelValue>, commit = true) => {
    const next = { ...latestValue.current, ...patch };
    latestValue.current = next;
    if (value === undefined) setInternalValue(next);
    onChange?.(next);
    pending.current = !commit;
    if (commit) onChangeEnd?.(next);
  };

  const commit = () => {
    if (!pending.current) return;
    pending.current = false;
    onChangeEnd?.(latestValue.current);
  };

  return (
    <section
      data-slot="light-sphere-panel"
      aria-label="3D 打光"
      className={`nodrag h-[320px] w-[560px] max-w-full overflow-hidden rounded-[20px] border border-white/[0.08] bg-[#191919] font-sans text-white shadow-[0_22px_70px_rgba(0,0,0,0.56)] max-[480px]:h-auto ${className}`}
      style={style}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => event.stopPropagation()}
    >
      <div className="grid h-full min-h-0 grid-cols-[minmax(0,300fr)_minmax(220px,260fr)] max-[480px]:grid-cols-1">
        <div className="relative min-w-0 overflow-hidden bg-[#20201f] max-[480px]:h-[300px]">
          <div className="absolute left-1/2 top-3 z-[4] grid h-7 w-[88px] -translate-x-1/2 grid-cols-2 gap-0.5 rounded-[9px] bg-black/20 p-1" aria-label="预览视角">
            {(["perspective", "front"] as const).map((mode) => (
              <button
                key={mode}
                type="button"
                aria-pressed={currentValue.viewMode === mode}
                className={`cursor-pointer rounded-[7px] border-0 text-[10px] font-semibold leading-none transition-colors focus-visible:outline focus-visible:outline-1 focus-visible:outline-white/25 ${currentValue.viewMode === mode ? "bg-white/15 text-white/90" : "bg-transparent text-white/35"}`}
                onClick={() => update({ viewMode: mode })}
              >
                {mode === "perspective" ? "透视" : "正面"}
              </button>
            ))}
          </div>
          <div className="absolute left-1/2 top-[48px] size-[200px] -translate-x-1/2 overflow-hidden rounded-full [&_canvas]:touch-none">
            <LightSphere
              imageUrl={imageUrl}
              {...BEAM_CONFIG}
              color={colorTemperatureToHex(currentValue.colorTemperature)}
              intensity={currentValue.intensity}
              sphereRadius={SPHERE_RADIUS}
              viewMode={currentValue.viewMode}
              targetPosition={currentValue.position}
              onLightSettle={(position) => {
                const current = latestValue.current;
                const activePosition = resolveLightPositionPresetKey(position);
                if (Math.abs(position.x - current.position.x) < 0.002 && Math.abs(position.y - current.position.y) < 0.002 && Math.abs(position.z - current.position.z) < 0.002 && activePosition === current.activePosition) return;
                update({ position, activePosition });
              }}
            />
          </div>
          <div className="absolute inset-x-0 bottom-3 flex items-center justify-center">
            <span className="rounded-t-[9px] border border-white/[0.08] bg-black/20 px-4 py-1 text-[10px] font-semibold italic text-white/55">主光源</span>
            <button
              type="button"
              aria-label="重置打光"
              className="absolute right-3 inline-flex cursor-pointer items-center gap-1 rounded-md px-1.5 py-1 text-[10px] text-white/30 transition-colors hover:bg-white/5 hover:text-white/60 focus-visible:outline focus-visible:outline-2 focus-visible:outline-white/60"
              onClick={() => update(normalizeValue())}
            >
              <RotateCcw size={12} aria-hidden="true" />重置
            </button>
          </div>
        </div>
        <aside className="flex min-h-0 min-w-0 flex-col border-l border-white/[0.06] bg-[#191919] px-3 pb-2.5 pt-2.5 max-[480px]:border-l-0 max-[480px]:border-t">
          <LightingControls
            values={currentValue}
            onBrightnessChange={(intensity) => update({ intensity }, false)}
            onColorTemperatureChange={(colorTemperature) => update({ colorTemperature }, false)}
            onPositionChange={(key) => {
              const preset = LIGHT_POSITION_PRESETS.find((item) => item.key === key);
              if (!preset) return;
              const point = sphericalPoint(preset.lat, preset.lon, SPHERE_RADIUS);
              update({ activePosition: key, position: { x: point.x, y: point.y, z: point.z } });
            }}
            onRimLightChange={(rimLightEnabled) => update({ rimLightEnabled })}
            onClose={onClose}
            onInteractionEnd={commit}
          />
          <div className="mt-auto flex justify-end pt-1.5">
            <ActionButton
              className="inline-flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-full bg-white p-0 text-black shadow-sm transition-colors hover:bg-white/85 disabled:cursor-not-allowed disabled:bg-white/15 disabled:text-white/40 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white/60"
              value={currentValue}
              input={actionInput}
              loading={actionLoading}
              disabled={actionLoading || actionDisabled}
              onClick={(event) => {
                if (!actionLoading && !actionDisabled) onAction?.({ value: latestValue.current, input: actionInput }, event);
              }}
            />
          </div>
        </aside>
      </div>
    </section>
  );
}

