          aria-checked={values.rimLightEnabled}
          aria-label="轮廓光"
          className="group relative h-[18px] w-8 cursor-pointer rounded-full border-0 bg-white/15 p-0 transition-colors aria-checked:bg-white/85 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white/60"
          onClick={() => onRimLightChange(!values.rimLightEnabled)}
        >
          <span className="absolute left-0.5 top-0.5 size-3.5 rounded-full bg-white/60 shadow-sm transition-transform group-aria-checked:translate-x-3.5 group-aria-checked:bg-white" />
        </button>
      </section>
    </div>
  );
}

export function colorTemperatureToHex(kelvin: number) {
  const temperature = kelvin / 100;
  let red: number;
  let green: number;
  let blue: number;

  if (temperature <= 66) {
    red = 255;
    green = 99.4708025861 * Math.log(temperature) - 161.1195681661;
    blue =
      temperature <= 19
        ? 0
        : 138.5177312231 * Math.log(temperature - 10) - 305.0447927307;
  } else {
    red = 329.698727446 * Math.pow(temperature - 60, -0.1332047592);
    green = 288.1221695283 * Math.pow(temperature - 60, -0.0755148492);
    blue = 255;
  }

  const channelToHex = (channel: number) =>
    Math.min(255, Math.max(0, Math.round(channel)))
      .toString(16)
      .padStart(2, "0");

  return `#${channelToHex(red)}${channelToHex(green)}${channelToHex(blue)}`;
}

export type PhotoPlaneSize = {
  width: number;
  height: number;
};

const PHOTO_PLANE_LONG_EDGE = 1.78;
const FALLBACK_PHOTO_PLANE_SIZE: PhotoPlaneSize = {
  width: 1.12,
  height: PHOTO_PLANE_LONG_EDGE,
};

export function getPhotoPlaneSize(
  imageWidth: number,
  imageHeight: number,
): PhotoPlaneSize {
  if (imageWidth <= 0 || imageHeight <= 0) {
    return FALLBACK_PHOTO_PLANE_SIZE;
  }

  const aspectRatio = imageWidth / imageHeight;
  if (aspectRatio >= 1) {
    return {
      width: PHOTO_PLANE_LONG_EDGE,
      height: PHOTO_PLANE_LONG_EDGE / aspectRatio,
    };
  }

  return {
    width: PHOTO_PLANE_LONG_EDGE * aspectRatio,
    height: PHOTO_PLANE_LONG_EDGE,
  };
}

import {
  LIGHT_POSITION_PRESETS,
  SPHERE_RADIUS,
} from "../LightSphere.constants";
import type {
  LightPositionKey,
  Vector3Like,
} from "../LightSphere.types";
import { sphericalPoint } from "./geometry";

const PRESET_POSITION_TOLERANCE = 0.02;

export function resolveLightPositionPresetKey(
  position: Vector3Like,
): LightPositionKey | null {
  for (const preset of LIGHT_POSITION_PRESETS) {
    const presetPosition = sphericalPoint(
      preset.lat,
      preset.lon,
      SPHERE_RADIUS,
    );
    const distance = Math.hypot(
      position.x - presetPosition.x,
      position.y - presetPosition.y,
      position.z - presetPosition.z,
    );
    if (distance <= PRESET_POSITION_TOLERANCE) return preset.key;
  }

  return null;
}
